auto printOperation(CodeEmitter& emitter, BinaryL0Op op) -> LogicalResultForT<BinaryL0Op, ascendc::MulCastL0Op>
{
    auto& os = emitter.ostream();
    os << ascNamespace << "::" << op.getAPIName();
    printBinaryL0Params(emitter, op);
    return success();
}

